<?php
require_once 'config.php';require_login();$pdo=db();$projects=allowed_projects('view_project');$pid=(int)($_GET['project_id']??0);$employee=(int)($_GET['employee_id']??0);$from=(string)($_GET['from']??date('Y-m-01'));$to=(string)($_GET['to']??date('Y-m-d'));$status=(string)($_GET['status']??'approved');
if(!valid_date($from)||!valid_date($to)||$from>$to||!in_array($status,['approved','pending','rejected','all'],true))exit('Invalid report filters');
if($pid&&!can('view_report',$pid)){http_response_code(403);exit('No report permission');}
$permitted=array_values(array_map(fn($p)=>(int)$p['id'],array_filter($projects,fn($p)=>can('view_report',(int)$p['id']))));
$employees=$pdo->query('SELECT id,name FROM users ORDER BY name')->fetchAll();
$expenses=[];$advances=[];
if($permitted){$in=implode(',',array_fill(0,count($permitted),'?'));
 $sql="SELECT e.entry_date dt,p.title project,u.name employee,h.name head,e.amount,e.description note,e.status FROM expenses e JOIN projects p ON p.id=e.project_id JOIN expense_heads h ON h.id=e.head_id LEFT JOIN users u ON u.id=e.advance_employee_id WHERE e.project_id IN ($in) AND e.entry_date BETWEEN ? AND ?";
 $args=[...$permitted,$from,$to];if($pid){$sql.=' AND e.project_id=?';$args[]=$pid;}if($employee){$sql.=' AND e.advance_employee_id=?';$args[]=$employee;}if($status!=='all'){$sql.=' AND e.status=?';$args[]=$status;}$sql.=' ORDER BY e.entry_date,e.id';$s=$pdo->prepare($sql);$s->execute($args);$expenses=$s->fetchAll();
 $sql="SELECT a.advance_date dt,p.title project,u.name employee,a.amount,a.note FROM employee_advances a JOIN projects p ON p.id=a.project_id JOIN users u ON u.id=a.employee_id WHERE a.project_id IN ($in) AND a.advance_date BETWEEN ? AND ?";$args=[...$permitted,$from,$to];if($pid){$sql.=' AND a.project_id=?';$args[]=$pid;}if($employee){$sql.=' AND a.employee_id=?';$args[]=$employee;}$sql.=' ORDER BY a.advance_date,a.id';$s=$pdo->prepare($sql);$s->execute($args);$advances=$s->fetchAll();}
$totalAdvance=array_sum(array_column($advances,'amount'));$totalExpense=array_sum(array_column($expenses,'amount'));
$grouped=[];foreach($expenses as $r){$key=$r['project'].' / '.$r['head'];$grouped[$key]=($grouped[$key]??0)+(float)$r['amount'];}
if(($_GET['format']??'')==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="jv_report.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Type','Date','Project','Employee','Head','Amount','Note','Status']);foreach($advances as $r)fputcsv($out,['Advance',$r['dt'],$r['project'],$r['employee'],'',$r['amount'],$r['note'],'']);foreach($expenses as $r)fputcsv($out,['Expense',$r['dt'],$r['project'],$r['employee'],$r['head'],$r['amount'],$r['note'],$r['status']]);fclose($out);exit;
}
include 'layout_top.php';?>
