<section class="page-title"><div><h1>দৈনিক / মাসিক / তারিখভিত্তিক রিপোর্ট</h1><p>তারিখ, প্রকল্প ও কর্মী দিয়ে ফিল্টার করুন। Print থেকে Save as PDF নির্বাচন করুন।</p></div></section>
<section class="panel no-print"><form method="get" class="form-grid"><div><label>শুরু</label><input type="date" name="from" value="<?=e($from)?>" required></div><div><label>শেষ</label><input type="date" name="to" value="<?=e($to)?>" required></div><div><label>প্রকল্প</label><select name="project_id"><option value="0">সব অনুমোদিত প্রকল্প</option><?php foreach($projects as $p):if(!can('view_report',(int)$p['id']))continue;?><option value="<?=$p['id']?>" <?=$pid===$p['id']?'selected':''?>><?=e($p['title'])?></option><?php endforeach;?></select></div><div><label>কর্মী</label><select name="employee_id"><option value="0">সব কর্মী</option><?php foreach($employees as $u):?><option value="<?=$u['id']?>" <?=$employee===$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach;?></select></div><div><label>ব্যয়ের অবস্থা</label><select name="status"><?php foreach(['approved','pending','rejected','all'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></div><button class="btn primary">রিপোর্ট দেখুন</button></form><p><button class="btn" onclick="window.print()">Print / Save as PDF</button> <a class="btn" href="?<?=e(http_build_query(array_merge($_GET,['format'=>'csv'])))?>">CSV Download</a></p></section>
<section class="panel"><h2>রিপোর্ট: <?=e($from)?> থেকে <?=e($to)?></h2><p>অগ্রিম: <b>৳<?=number_format($totalAdvance,2)?></b> | নির্বাচিত ব্যয়: <b>৳<?=number_format($totalExpense,2)?></b> | পার্থক্য: <b>৳<?=number_format($totalAdvance-$totalExpense,2)?></b></p><small>পার্থক্য শুধুমাত্র নির্বাচিত সময়সীমার অগ্রিম ও ব্যয়ের ব্যবধান; এটি কর্মীর মোট বকেয়া ব্যালেন্স নয়।</small></section>
<section class="panel"><h2>অগ্রিমের তালিকা</h2><div class="table-wrap"><table><thead><tr><th>তারিখ</th><th>প্রকল্প</th><th>কর্মী</th><th>টাকা</th><th>বিবরণ</th></tr></thead><tbody><?php foreach($advances as $r):?><tr><td><?=e($r['dt'])?></td><td><?=e($r['project'])?></td><td><?=e($r['employee'])?></td><td>৳<?=number_format((float)$r['amount'],2)?></td><td><?=e($r['note'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>ব্যয়ের তালিকা</h2><div class="table-wrap"><table><thead><tr><th>তারিখ</th><th>প্রকল্প</th><th>কর্মী</th><th>খাত</th><th>টাকা</th><th>অবস্থা</th></tr></thead><tbody><?php foreach($expenses as $r):?><tr><td><?=e($r['dt'])?></td><td><?=e($r['project'])?></td><td><?=e($r['employee']?:'সাধারণ ব্যয়')?></td><td><?=e($r['head'])?></td><td>৳<?=number_format((float)$r['amount'],2)?></td><td><?=e($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>প্রকল্প ও খাতভিত্তিক ব্যয় সারসংক্ষেপ</h2><div class="table-wrap"><table><thead><tr><th>প্রকল্প / খাত</th><th>মোট</th></tr></thead><tbody><?php foreach($grouped as $k=>$v):?><tr><td><?=e($k)?></td><td>৳<?=number_format($v,2)?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php include 'layout_bottom.php';?>
